params.command:
$ErrorActionPreference='Stop';
$repo='C:\Users\Xxkan\HeavenBridgeRepo';
git -C $repo fetch origin main;
if($LASTEXITCODE -ne 0){throw 'fetch main failed'}
$tmp=Join-Path $env:TEMP 'install-github-runner-heaven.ps1';
git -C $repo show origin/main:heaven-bridge/install-github-runner.ps1 | Set-Content -LiteralPath $tmp -Encoding UTF8;
if($LASTEXITCODE -ne 0){throw 'extract runner installer failed'}
& powershell.exe -NoProfile -ExecutionPolicy Bypass -File $tmp;
$code=$LASTEXITCODE;
Remove-Item $tmp -Force -ErrorAction SilentlyContinue;
exit $code
